function G([string[]]$a,[switch]$ok){$o=& git @a 2>&1;$c=$LASTEXITCODE;if(!$ok-and$c-ne0){throw("git "+($a-join' ')+" failed "+$c+": "+($o-join' '))};[pscustomobject]@{c=$c;o=@($o)}}
[void](G @('-C',$r,'fetch','origin','--prune'))
$baseline=((G @('-C',$r,'rev-parse','origin/main')).o|Select-Object -First 1).Trim()
# Require the canonical disposition ledgers to still exist on this exact main.
foreach($f in @('_AGENT_CONTEXT/SUPPORT_BRANCH_INTEGRATION_2026-09-27.md','_AGENT_CONTEXT/SUPPORT_BRANCH_INTEGRATION_2026-09-28.md')){
  if((G @('-C',$r,'cat-file','-e',('origin/main:'+$f)) -ok).c-ne0){throw "canonical disposition ledger missing: $f"}
}
$current=((G @('-C',$r,'branch','--show-current')).o|Select-Object -First 1).Trim()
$wt=[System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
foreach($l in (G @('-C',$r,'worktree','list','--porcelain')).o){$x=[string]$l;if($x.StartsWith('branch refs/heads/')){[void]$wt.Add($x.Substring(18))}}
$dr=@();$dl=@();$absent=@();$keep=@()
foreach($t in $targets){
 $b=$t.b
 if($b-eq'main'-or$b-eq'heaven-bridge'-or$b.StartsWith('release/')-or$b-eq$current-or$wt.Contains($b)){$keep+=@([pscustomobject]@{branch=$b;reason='current/worktree/reserved'});continue}
 $ls=G @('-C',$r,'ls-remote','--heads','origin',('refs/heads/'+$b)) -ok
 if($ls.c-ne0-or!$ls.o.Count){$absent+=$b;continue}
 $live=(([string]$ls.o[0])-split'\s+')[0]
 if($live-ne$t.tip){$keep+=@([pscustomobject]@{branch=$b;reason=('tip moved '+$t.tip+' -> '+$live)});continue}
 if((G @('-C',$r,'show-ref','--verify','--quiet',('refs/heads/'+$b)) -ok).c-eq0){
   $x=G @('-C',$r,'branch','-D','--',$b) -ok
   if($x.c-ne0){$keep+=@([pscustomobject]@{branch=$b;reason='local delete failed'});continue}else{$dl+=$b}
 }
 $x=G @('-C',$r,'push','origin','--delete',$b) -ok
 if($x.c-eq0){$dr+=$b}else{$keep+=@([pscustomobject]@{branch=$b;reason=('remote delete failed '+($x.o-join' '))})}
}
$pr=G @('-C',$r,'remote','prune','origin') -ok
[void](G @('-C',$r,'fetch','origin','--prune') -ok)
$final=((G @('-C',$r,'rev-parse','origin/main')).o|Select-Object -First 1).Trim()
[ordered]@{baseline_origin_main=$baseline;final_origin_main=$final;deleted_local=$dl;deleted_remote=$dr;already_absent=$absent;preserved=$keep;prune=@($pr.o)}|ConvertTo-Json -Depth 6
